{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "RU-505, which shares the same pyrazolo[1,5-a]pyrimidine carboxamide core and 4-fluorophenyl substituent as the query, showed brain levels equal to or greater than blood levels over 24 h after subcutaneous dosing in mice, directly supporting meaningful CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A primary carboxamide-containing analogue showed excellent brain permeability by PET in rats (SUVmax 3.6), indicating that the primary amide in the query does not prevent BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A primary carboxamide analogue achieved a brain:blood ratio of 3.5 in rat in vivo exposure studies, supporting high CNS penetration despite the presence of an amide and moderate polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "VU6043653, an amide-containing heteroaromatic CNS compound, had a rat brain:plasma Kp of 1.68 and was classified as having excellent CNS penetration, supporting the query's amide/heteroaromatic profile.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "GNE-0723, a related fused heteroaromatic compound, showed excellent brain penetration with similar unbound plasma and brain concentrations and no active efflux, supporting that this chemotype can achieve adequate CNS exposure without being limited by transporters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "JNJ-55308942, a related fused heteroaromatic amide, partitioned efficiently into rat brain with a brain/plasma ratio close to unity after oral administration, supporting adequate CNS access for this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental analogues, including the same pyrazolo[1,5-a]pyrimidine carboxamide core, demonstrate robust brain penetration in rodents and non-human primates, with brain/plasma ratios at or above unity and no evidence of efflux limitation. The query's moderate physicochemical prior is therefore overridden by strong, directly transferable in vivo evidence.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule, but multiple close analogues with the same core and amide provide strong transferable evidence.",
    "No explicit efflux ratio for the query itself, though a related compound in the evidence set showed no active efflux.",
    "No human PET or pharmacokinetic data for the exact query, but human translatability is supported by related PET ligands."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

